"use client";
import type { HTMLAttributes } from "react";
import "./beam-card.css";

/** A surface with a slow comet of light travelling around its border. */
export function BeamCard({ children, className = "", ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div {...props} className={`forme-beam ${className}`}>
      <span className="forme-beam-light" aria-hidden="true" />
      {children}
    </div>
  );
}

@property --forme-beam-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.forme-beam {
  --forme-beam-color: #8ab4ff;
  position: relative;
  box-sizing: border-box;
  padding: 24px;
  border-radius: 18px;
  background: linear-gradient(180deg, #121215, #0a0a0c);
  box-shadow: inset 0 0 0 1px #ffffff14;
  color: #f4f4f5;
}
.forme-beam-light {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    from var(--forme-beam-angle),
    transparent 0deg 290deg,
    color-mix(in srgb, var(--forme-beam-color), transparent 70%) 330deg,
    var(--forme-beam-color) 356deg,
    #fff 360deg
  );
  animation: forme-beam-orbit 7s linear infinite;
  pointer-events: none;
}
.forme-beam-light {
  padding: 1px;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}
@keyframes forme-beam-orbit {
  to {
    --forme-beam-angle: 360deg;
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-beam-light {
    animation: none;
    --forme-beam-angle: 220deg;
  }
}
